(1, 'Red Bull Racing', 'Oracle Red Bull Racing', 'Milton Keynes UK', '2005-01-01', 'Fondée sur les bases de Jaguar Racing. Force dominante depuis les années 2010.', '6 titres constructeurs, plus de 120 victoires.', 'Pierre Waché', 'Laurent Mekies'),
(2, 'Ferrari', 'Scuderia Ferrari HP', 'Maranello Italy', '1950-05-21', 'Seule écurie à avoir participé à chaque saison depuis 1950.', '16 titres constructeurs (record).', 'Loïc Serra', 'Frédéric Vasseur'),
(3, 'Mercedes', 'Mercedes-AMG Petronas F1 Team', 'Brackley UK', '2010-01-01', 'Revenue en F1 en tant qu\'écurie d\'usine après le rachat de Brawn GP.', '8 titres constructeurs consécutifs (2014-2021).', 'James Allison', 'Toto Wolff'),
(4, 'McLaren', 'McLaren Formula 1 Team', 'Woking UK', '1966-05-22', 'Deuxième plus ancienne écurie et l\'une des plus titrées.', '8 titres constructeurs, vainqueur 2025.', 'Rob Marshall', 'Andrea Stella'),
(5, 'Aston Martin', 'Aston Martin Aramco F1 Team', 'Silverstone UK', '2021-01-01', 'Anciennement Racing Point. Projet ambitieux pour devenir une écurie de pointe.', 'Multiples podiums depuis 2023.', 'Adrian Newey', 'Andy Cowell'),
(6, 'Williams', 'Atlassian Williams F1 Team', 'Grove UK', '1977-05-08', 'Écurie historique fondée par Sir Frank Williams.', '9 titres constructeurs.', 'Pat Fry', 'James Vowles'),
(7, 'Haas', 'TGR Haas F1 Team', 'Kannapolis USA', '2016-03-20', 'Écurie américaine utilisant un partenariat étroit avec Ferrari et Toyota.', 'Meilleur résultat : 5e au championnat (2018).', 'Ayao Komatsu', 'Ayao Komatsu'),
(8, 'Racing Bulls', 'Visa Cash App Racing Bulls', 'Faenza Italy', '2006-03-12', 'Anciennement AlphaTauri et Toro Rosso. Écurie sœur de Red Bull.', '2 victoires en Grand Prix (2008, 2020).', 'Guillaume Cattelani', 'Laurent Mekies'),
(9, 'Audi', 'Audi F1 Team', 'Hinwil Switzerland', '2026-01-01', 'Projet d\'usine Audi basé sur les infrastructures de Sauber.', 'En phase de transformation technologique majeure.', 'James Key', 'Jonathan Wheatley'),
(10, 'Cadillac', 'Cadillac Formula 1 Team', 'Charlotte USA', '2026-03-01', 'Nouvelle 11ème écurie sur la grille pour la saison 2026.', 'Débuts prévus pour le championnat 2026.', 'Graeme Lowdon', 'Graeme Lowdon'),
(11, 'Alpine', 'BWT Alpine Formula One Team', 'Enstone UK', '2021-01-01', 'Écurie d\'usine du Groupe Renault, succédant à Renault F1.', 'Victoire au Grand Prix de Hongrie 2021.', 'Joe Burnell', 'Oliver Oakes');
